#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# deploy.sh — Pull latest code and rebuild the Signalium Trainer stack
# -----------------------------------------------------------------------------
# Run this on the VPS to apply a new release in one command:
#
#   bash deploy/scripts/deploy.sh
#
# What it does:
#   1. Resets any local changes that would block git pull (e.g. pnpm-lock.yaml
#      regenerated by an earlier --no-frozen-lockfile install).
#   2. Pulls the latest commit from the configured upstream branch.
#   3. Delegates to restart.sh with REBUILD=1, which installs deps, builds both
#      services, prunes to prod-only modules, and reloads PM2.
# -----------------------------------------------------------------------------
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

info()  { echo "[INFO]  $*"; }
warn()  { echo "[WARN]  $*"; }
error() { echo "[ERROR] $*" >&2; exit 1; }

# ---------------------------------------------------------------------------
# 1. Reset files that are re-generated on each install so git pull won't block
# ---------------------------------------------------------------------------
RESET_FILES=(pnpm-lock.yaml)
for f in "${RESET_FILES[@]}"; do
  if [[ -f "$f" ]] && ! git diff --quiet HEAD -- "$f" 2>/dev/null; then
    info "Resetting $f (locally modified by previous install)..."
    git checkout HEAD -- "$f"
  fi
done

# ---------------------------------------------------------------------------
# 2. Pull latest code
# ---------------------------------------------------------------------------
BRANCH="${DEPLOY_BRANCH:-$(git rev-parse --abbrev-ref HEAD)}"
info "Pulling latest from origin/$BRANCH..."
git fetch origin "$BRANCH"
git reset --hard "origin/$BRANCH"
info "Now at $(git rev-parse --short HEAD) — $(git log -1 --format='%s')"

# ---------------------------------------------------------------------------
# 3. Build and reload
# ---------------------------------------------------------------------------
info "Rebuilding and reloading services..."
REBUILD=1 bash "$(dirname "${BASH_SOURCE[0]}")/restart.sh"
